-- ============================================================
-- Core Banking
-- Schema 013: Independent Account Serial per Account Type
-- PostgreSQL
--
-- Each account type has its own incrementing 10-digit serial.
-- The final account number is generated by the application:
-- account type code (2 digits) + serial (10 digits) + check digit.
-- ============================================================

BEGIN;

CREATE TABLE account_type_account_serial
(
    account_type_id BIGINT PRIMARY KEY,

    last_serial BIGINT NOT NULL DEFAULT 0,

    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_account_type_account_serial_type
        FOREIGN KEY (account_type_id)
        REFERENCES account_type(id),

    CONSTRAINT ck_account_type_account_serial_range
        CHECK (
            last_serial >= 0
            AND last_serial <= 9999999999
        )
);

-- Initialize counters from existing account numbers.
-- This prevents newly opened accounts from reusing an existing
-- serial for the same account type.

INSERT INTO account_type_account_serial
(
    account_type_id,
    last_serial
)
SELECT
    at.id,
    COALESCE(
        MAX(
            SUBSTRING(a.account_number FROM 3 FOR 10)::BIGINT
        ),
        0
    )
FROM account_type AS at
LEFT JOIN account AS a
    ON a.account_type_id = at.id
GROUP BY at.id
ON CONFLICT (account_type_id)
DO UPDATE
SET
    last_serial = GREATEST(
        account_type_account_serial.last_serial,
        EXCLUDED.last_serial
    ),
    updated_at = CURRENT_TIMESTAMP;

COMMIT;
